function phoneListening(){const ds=[
 {title:'Dialog 1 · Café',file:'l8t4_telefon_01.mp3',audio:'Frau: Guten Tag. Ich habe Ihre Stellenanzeige für das Café gelesen. Ist die Stelle noch frei? Mann: Ja. Wir suchen noch eine Aushilfe. Frau: Wann arbeitet man? Mann: Montags bis freitags von acht bis zwölf Uhr. Frau: Und wie viel verdient man? Mann: Vierzehn Euro pro Stunde. Frau: Danke.',qs:[C('Die Anruferin möchte wissen, ob sie sich noch bewerben kann.',['Richtig','Falsch'],'Richtig'),C('Wann müsste sie arbeiten?',['am Vormittag','am Abend','nur am Wochenende'],'am Vormittag'),I('Wie hoch ist der Stundenlohn?',['14 Euro','vierzehn Euro','14 Euro pro Stunde'])]},
 {title:'Dialog 2 · Nachhilfe',file:'l8t4_telefon_02.mp3',audio:'Mann: Guten Tag. Ich rufe wegen der Nachhilfe-Stelle an. Frau: Ja, gern. Mann: Ich kann dienstags, aber donnerstags erst ab sechzehn Uhr. Ist das möglich? Frau: Ja. Wichtig ist nur, dass Sie bis achtzehn Uhr bleiben können. Mann: Das geht. Können wir uns morgen treffen? Frau: Ja, um zehn Uhr.',qs:[C('Der Mann kann an beiden Arbeitstagen kommen.',['Richtig','Falsch'],'Richtig'),C('Was ist für die Firma am Donnerstag wichtig?',['Er bleibt bis 18 Uhr.','Er beginnt um 8 Uhr.','Er arbeitet nachts.'],'Er bleibt bis 18 Uhr.'),I('Wann ist der Termin?',['morgen um zehn Uhr','morgen 10 Uhr','um zehn Uhr'])]},
 {title:'Dialog 3 · Universität',file:'l8t4_telefon_03.mp3',audio:'Frau: Guten Tag. Ich interessiere mich für die Stelle im Sekretariat. Ist sie befristet? Mann: Nein, die Stelle ist dauerhaft. Frau: Ist es Vollzeit? Mann: Ja, montags bis freitags. Frau: Brauche ich Berufserfahrung? Mann: Erfahrung im Büro ist gut. Computerkenntnisse sind aber besonders wichtig.',qs:[C('Die Bewerberin sucht Informationen zur Dauer der Stelle.',['Richtig','Falsch'],'Richtig'),C('Was ist besonders wichtig?',['Computerkenntnisse','ein Führerschein','Arbeit am Wochenende'],'Computerkenntnisse'),I('Ist die Stelle befristet?',['nein','Nein','Nein, sie ist dauerhaft.'])]},
 {title:'Dialog 4 · Seniorenhilfe',file:'l8t4_telefon_04.mp3',audio:'Mann: Guten Tag. Ist die Stelle bei der Seniorenhilfe noch frei? Frau: Ja. Können Sie samstags und sonntags arbeiten? Mann: Ja, vormittags habe ich Zeit. Frau: Haben Sie einen Führerschein? Mann: Ja. Frau: Gut. Dann kommen Sie bitte am Freitag um vierzehn Uhr zu einem Gespräch.',qs:[C('Die Arbeitszeit passt zum Anrufer.',['Richtig','Falsch'],'Richtig'),C('Warum passt der Mann gut?',['Er kann am Wochenende arbeiten und fährt Auto.','Er arbeitet nur nachts.','Er hat eine Universität.'],'Er kann am Wochenende arbeiten und fährt Auto.'),I('Wann soll er zum Gespräch kommen?',['Freitag um 14 Uhr','am Freitag um 14 Uhr','Freitag vierzehn Uhr'])]},
 {title:'Dialog 5 · Hotel',file:'l8t4_telefon_05.mp3',audio:'Frau: Guten Tag. Ich habe Ihre Anzeige für den Service gelesen. Ich habe noch nicht im Hotel gearbeitet. Kann ich mich trotzdem bewerben? Mann: Ja. Erfahrung ist nicht notwendig. Frau: Ich kann freitags und samstags ab siebzehn Uhr. Mann: Das passt sehr gut. Frau: Wie viel verdient man? Mann: Sechzehn Euro pro Stunde.',qs:[C('Fehlende Hotelerfahrung ist kein Problem.',['Richtig','Falsch'],'Richtig'),C('Warum passt ihre Zeit?',['Sie kann genau an den benötigten Abenden arbeiten.','Sie kann nur morgens.','Sie kann nie am Samstag.'],'Sie kann genau an den benötigten Abenden arbeiten.'),I('Wie viel bekommt man pro Stunde?',['16 Euro','sechzehn Euro','16 Euro pro Stunde'])]}
 ];const items=[];const dialogues=[];ds.forEach((d,di)=>{const start=items.length;d.qs.forEach(q=>items.push({...q,context:d.title,audio:d.audio,audioFile:AUDIO+d.file}));dialogues.push({title:d.title,audio:d.audio,audioFile:AUDIO+d.file,fileName:d.file,questionIndexes:[start,start+1,start+2]})});return{id:'l8t4-hoeren-telefon',title:'Hören: Telefon',kind:'listening',icon:'📞',emoji:'📞',spL8T4ListeningGroups:true,instruction:'Höre den Dialog. Beantworte die Fragen.',items,dialogues}}
